enum nss_status get_group_info(const char* name, struct group* gr, char* buffer, size_t buflen, int* errnop) {
    if (!name || !gr || !buffer || buflen == 0 || !errnop) {
        *errnop = EINVAL;
        return NSS_STATUS_UNAVAIL;
    }

    // Placeholder for extracting machine name and group ID from `name`
    // Replace with actual logic to parse or retrieve group ID
    char machine_name[256] = {0};
    gid_t gid = 0;

    // Validate and parse input name
    if (strlen(name) >= sizeof(machine_name)) {
        *errnop = ENAMETOOLONG;
        return NSS_STATUS_UNAVAIL;
    }
    strcpy(machine_name, name);

    // Initialize sd-bus
    sd_bus* bus = NULL;
    int r = sd_bus_default_system(&bus);
    if (r < 0) {
        *errnop = -r;
        return NSS_STATUS_UNAVAIL;
    }

    sd_bus_message* msg = NULL;
    r = sd_bus_message_new_method_call(
        bus,
        "org.freedesktop.machine1",
        "/org/freedesktop/machine1",
        "org.freedesktop.machine1.Manager",
        "MapGroup",
        &msg);
    if (r < 0) {
        *errnop = -r;
        sd_bus_unref(bus);
        return NSS_STATUS_UNAVAIL;
    }

    r = sd_bus_message_append(msg, "ss", machine_name, name);
    if (r < 0) {
        *errnop = -r;
        sd_bus_message_unref(msg);
        sd_bus_unref(bus);
        return NSS_STATUS_UNAVAIL;
    }

    sd_bus_message* reply = NULL;
    r = sd_bus_call(bus, msg, 0, NULL, &reply);
    if (r < 0) {
        *errnop = -r;
        sd_bus_message_unref(reply);
        sd_bus_unref(bus);
        return NSS_STATUS_UNAVAIL;
    }

    const char* mapped_name = NULL;
    r = sd_bus_message_read(reply, "s", &mapped_name);
    if (r < 0) {
        *errnop = -r;
        sd_bus_message_unref(reply);
        sd_bus_unref(bus);
        return NSS_STATUS_UNAVAIL;
    }

    if (!mapped_name) {
        *errnop = ENOENT;
        sd_bus_message_unref(reply);
        sd_bus_unref(bus);
        return NSS_STATUS_NOTFOUND;
    }

    // Copy the mapped name into the provided buffer
    if (strlen(mapped_name) >= buflen) {
        *errnop = ERANGE;
        sd_bus_message_unref(reply);
        sd_bus_unref(bus);
        return NSS_STATUS_UNAVAIL;
    }

    strcpy(buffer, mapped_name);
    gr->gr_name = buffer;
    gr->gr_gid = gid;
    gr->gr_mem = NULL;  // No members provided by this method

    sd_bus_message_unref(reply);
    sd_bus_unref(bus);
    *errnop = 0;
    return NSS_STATUS_SUCCESS;
}

